from pydantic import BaseModel, ConfigDict, Field, ValidationError


class GenerateRequest(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    prompt: str = Field(min_length=1, max_length=2000)
    max_new_tokens: int = Field(ge=1, le=256)


for body in (
    {"prompt": "hi", "max_new_tokens": 16},
    {"prompt": "hi", "max_new_tokens": 100000},
    {"prompt": "", "max_new_tokens": 16, "temperature": 2},
):
    try:
        job = GenerateRequest.model_validate(body)
        print("admitted:", job.model_dump())
    except ValidationError as error:
        print("422:", [(e["loc"][0], e["type"]) for e in error.errors()])

