import numpy as np

logits = np.array([2.0, 1.0, 0.5, -1.0])


def probabilities(temperature, top_k=None):
    scaled = logits / temperature
    if top_k is not None:
        cutoff = np.sort(scaled)[-top_k]
        scaled = np.where(scaled >= cutoff, scaled, -np.inf)
    exp = np.exp(scaled - scaled.max())
    return np.round(exp / exp.sum(), 3)


for temperature, top_k in ((1.0, None), (0.5, None), (2.0, None), (1.0, 2)):
    print("T", temperature, "top_k", top_k, probabilities(temperature, top_k))

lengths = [2, 8, 3, 2]
static_steps = max(lengths)
static_finish = [static_steps] * len(lengths)
slots, waiting, running, step, finish = 2, list(enumerate(lengths)), {}, 0, {}
while waiting or running:
    while waiting and len(running) < slots:
        index, remaining = waiting.pop(0)
        running[index] = remaining
    step += 1
    for index in list(running):
        running[index] -= 1
        if running[index] == 0:
            finish[index] = step
            del running[index]
print("static batch of 4, finish steps:", static_finish)
print("continuous with 2 slots, finish steps:", [finish[i] for i in range(len(lengths))])

gates = {"p95_ttft_s": ("<=", 1.0), "error_rate": ("<=", 0.01), "eval_pass_rate": (">=", 0.95)}
candidates = {
    "v7": {"p95_ttft_s": 0.8, "error_rate": 0.004, "eval_pass_rate": 0.96},
    "v8": {"p95_ttft_s": 0.6, "error_rate": 0.002},
}
for name, measured in candidates.items():
    results = {}
    for metric, (op, limit) in gates.items():
        value = measured.get(metric)
        results[metric] = (
            "missing" if value is None else (value <= limit if op == "<=" else value >= limit)
        )
    decision = "release" if all(r is True for r in results.values()) else "hold"
    print(name, results, decision)
